% related_work.tex — D048 deep writing optimization

\section{Related Work}

\paragraph{Multi-turn jailbreak attacks.}
All multi-turn jailbreak families share a persuasion substrate~\citep{zeng2024pap,hagendorff2026reasoning,li2024mhj}, yet each operationalizes it differently: Crescendo~\citep{russinovich2024crescendo} gradually escalates, FITD~\citep{fitd2024} exploits commitment-consistency bias, DD~\citep{deceptivedelight2024} combines emotional manipulation with role assignment, ActorAttack~\citep{ren2024actorattack} steers through multiple personas, and automated methods (PAIR~\citep{chao2023pair}, TAP~\citep{mehrotra2024tap}) iteratively refine adversarial prompts, extending the automated red-teaming paradigm~\citep{perez2022redteaming}. \citet{wei2023jailbroken} provide a unifying taxonomy; RED QUEEN~\citep{jiang2024redqueen} constructs concealed multi-turn scenarios across 14 harmful categories; benchmarks~\citep{mazeika2024harmbench,chao2024jailbreakbench} standardize single-turn comparison, while MultiBreak~\citep{song2026multibreak} targets multi-turn evaluation. This shared substrate with diverse surface strategies defines our evaluation: a detector must generalize across families, not merely succeed on its training distribution.

\paragraph{Multi-turn defenses and production safety.}
No existing defense evaluates cross-attack transfer. Recent conversation-level systems pair fine-tuned encoders with sequence-level aggregation via GRU hierarchies (DeepContext~\citep{deepcontext2026}), turn-intention inference (BIID~\citep{tong2025biid}), graph neural networks (G-Guard~\citep{gguard2025}), or predictive generation (SafeDream~\citep{safedream2026}), yet each evaluates on a single attack family. Representation-level approaches include X-Boundary~\citep{lu2025xboundary}, JBShield~\citep{zhang2025jbshield} via activated concept analysis, latent activation probing~\citep{kulkarni2026latentadversarial,kadali2026trace}, and vision-language detection~\citep{hua2026rcs}; these require white-box access and can be brittle under adaptive attacks~\citep{derya2026revisitingjbshield}. Our work uses black-box classification with systematic cross-attack OOD evaluation. Per-turn classifiers (Llama Guard~\citep{inan2023llamaguard,metallamaguard3_2024}, ShieldGemma~\citep{zeng2024shieldgemma}, WildGuard~\citep{han2024wildguard}, Constitutional Classifiers~\citep{anthropic2025constitutional}) cannot model multi-turn trajectories, and perturbation-based defenses~\citep{robey2024smoothllm} target single-turn token-level attacks. Our ablation fills this gap: decomposition across thirteen configurations under OOD evaluation identifies domain exposure as the dominant factor behind cross-attack transfer.

\paragraph{Computational persuasion and discourse.}
Persuasion and discourse frameworks offer interpretable vocabulary for attack strategies, but whether such structure aids detection has not been empirically disentangled. Foundational work (RST~\citep{mann1988rst}, PDTB~\citep{prasad2008pdtb}, dialogue acts~\citep{stolcke2000dialogueact}, Speech Act Theory~\citep{austin1962speechacts,searle1969speechacts}) models pragmatic structure at different granularities. Building on Cialdini's principles~\citep{cialdini2001influence}, PAP~\citep{zeng2024pap} identifies 40 persuasion techniques across jailbreak families, and \citet{hagendorff2026reasoning} find identifiable strategies in 97\% of successful attacks; propaganda analysis~\citep{dasanmartino2019fine,dasanmartino2020semeval} and persuasive dialogue~\citep{wang2019persuasion} apply similar technique-level classification. Our ablation disentangles these roles: the taxonomy enables interpretable strategy characterization, but detection operates through domain-adapted embeddings regardless of label correctness.

\paragraph{Domain-adaptive pretraining.}
Continued pretraining on unlabeled domain text yields consistent downstream gains~\citep{gururangan2020dontstop}, extending the pretrain-then-fine-tune approach of ULMFiT~\citep{howard2018ulmfit}, yet this mechanism has not been disentangled for safety-critical generalization. Intermediate-task transfer (STILTs~\citep{phang2018stilts}) and multi-task learning~\citep{caruana1997multitask,liu2019mtdnn} offer complementary paths but confound domain exposure with supervised signal. Our MLM control removes all classification labels and confirms that pretraining alone closes the OOD gap. Dataset artifact analysis~\citep{gururangan2018artifacts,niven2019probing} motivates our TF-IDF baseline, adversarial NLP methods~\citep{jin2020textfooler,li2020bertattack,nasr2025attackermovessecond,andriushchenko2024adaptive} inform the perturbation protocol, and probing techniques~\citep{conneau2018probing,hewitt2019structural} underpin the CKA analysis.

% checklist.tex — ARR Responsible NLP Research Checklist

\section*{Responsible NLP Research Checklist}

\paragraph{A. Limitations.}
\begin{enumerate}[label=A\arabic*.,leftmargin=2em]
  \item Did you describe the limitations of your work? \textbf{Yes.} Section~\ref{sec:limitations} discusses dataset scale, lexical separability, annotation quality, OOD strategy prediction, single-seed variants, scope, and compute cost.
  \item Did you discuss any potential risks of your work? \textbf{Yes.} See below.
\end{enumerate}

\paragraph{B. Potential Risks and Ethical Considerations.}
This work studies multi-turn jailbreak attacks against LLMs. While the analysis is defensive (improving detection), we acknowledge dual-use risk: the persuasion taxonomy and attack strategy analysis could inform adversarial actors. We mitigate this by: (1) using only synthetic conversations generated by an open-weight model (Qwen3-8B), not real attack data targeting production systems; (2) not releasing attack-generation prompts that could enable novel attacks; (3) focusing the contribution on detection mechanisms rather than attack techniques. All jailbreak conversations are synthetic and do not contain real harmful content. No human subjects were involved.

\paragraph{C. Computational Experiments.}
\begin{enumerate}[label=C\arabic*.,leftmargin=2em]
  \item Did you report the number of parameters in the models used? \textbf{Yes.} DeBERTa-v3-base (184M) and RoBERTa-base (125M) in Sections~\ref{sec:method} and~\ref{sec:discussion}.
  \item Did you report the total amount of compute and the type of resources used? \textbf{Yes.} Under 4 GPU-hours total on a single NVIDIA A100 (40GB). Section~\ref{sec:limitations} and Appendix~\ref{sec:reproducibility}.
  \item Did you report the implementation details sufficient for reproducibility? \textbf{Yes.} Appendix~\ref{sec:reproducibility} provides all hyperparameters. We will release code and data upon acceptance.
  \item Did you report error bars or confidence intervals? \textbf{Yes.} All OOD results report 3-seed mean$\pm$std (population standard deviation, $n$ divisor; Appendix~\ref{app:data_efficiency} uses Bessel-corrected $n{-}1$). Statistical tests (McNemar's, bootstrap CIs, permutation tests) are reported where applicable.
\end{enumerate}

\paragraph{D. Human Evaluation.}
Not applicable. No human evaluation was conducted. Strategy annotation quality was validated against a human sample ($n$=50, $\kappa$=0.78) but this was a validation check, not a full human evaluation study.

\paragraph{E. Existing Assets.}
\begin{enumerate}[label=E\arabic*.,leftmargin=2em]
  \item Did you cite the creators of artifacts you used? \textbf{Yes.} DeBERTa-v3~\citep{he2023debertav3}, RoBERTa~\citep{liu2019roberta}, Qwen3-8B~\citep{qwen3_2025} (for data generation).
  \item Did you discuss the license or terms for use and/or distribution of any artifacts? \textbf{Yes.} The training and evaluation data are synthetically generated and will be released under the CC BY-NC 4.0 license. Code will be released under MIT. DeBERTa-v3 is available under MIT; RoBERTa under MIT; Qwen3-8B under Apache 2.0.
  \item Did you discuss whether the data you are using contains personally identifiable information? \textbf{N/A.} All data is synthetically generated. No PII is present.
\end{enumerate}

